//! noevia#1318: native read-only `GET /api/v1/sections/{name}/autoconfig` through the real router.
//!
//! On Linux every case of `fixtures/section-autoconfig-python.v1.json` (the actual services
//! Python, regenerated by CI from the pinned ref) runs through the router and the kernel-contained
//! opener, with a stand-in for the Python child that answers the private runtime call with what
//! the real child answered for that case, and that records each request. Elsewhere that opener
//! refuses by design, which the refusal test asserts; the lib tests run the same cases on every
//! platform.
#![cfg(feature = "native-section-autoconfig")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing
)]
use axum::{body::Body, http::Request};
use http_body_util::BodyExt;
use noevia_model_manager::{
    section_autoconfig::{SectionAutoconfig, Settings, RUNTIME_PATH},
    Container, DockerRead, Redactor, StateData,
};
use std::{future::Future, path::Path, pin::Pin, sync::Arc};
use tower::ServiceExt;

const TOKEN: &str = "synthetic-model-loader-token-0123456789abcdef";
const REFUSED: &[u8] = br#"{"detail":"Native section autoconfig is unavailable"}"#;
const UNAVAILABLE: &[u8] = br#"{"detail":"Python-owned endpoint unavailable"}"#;
/// A GGUF v3 header with one key: general.architecture = "synth".
const HEADER: &str =
    "474755460300000000000000000000000100000000000000140000000000000067656e6572616c2e61726368697465637475726508000000050000000000000073796e7468";

type Job<'a, T> = Pin<Box<dyn Future<Output = Result<T, &'static str>> + Send + 'a>>;
struct NoDocker;
impl DockerRead for NoDocker {
    fn containers(&self) -> Job<'_, Vec<Container>> {
        Box::pin(async { Err("not used") })
    }
    fn logs<'a>(&'a self, _: &'a str, _: usize) -> Job<'a, Vec<u8>> {
        Box::pin(async { Err("not used") })
    }
}

fn state(native: Option<Arc<SectionAutoconfig>>, legacy_base: &str) -> Arc<StateData> {
    Arc::new(StateData {
        #[cfg(feature = "native-diagnose")]
        diagnosis: None,
        #[cfg(feature = "native-prompts")]
        prompts: None,
        #[cfg(feature = "native-settings")]
        settings: None,
        #[cfg(feature = "native-model-updates")]
        model_updates: None,
        #[cfg(feature = "native-model-detail")]
        model_detail: None,
        #[cfg(feature = "native-model-list")]
        model_list: None,
        sections: None,
        embedding: None,
        host: None,
        token: TOKEN.into(),
        configured: vec![],
        docker: Arc::new(NoDocker),
        redactor: Redactor::new().unwrap(),
        permits: tokio::sync::Semaphore::new(4),
        legacy: noevia_model_manager::legacy_client().unwrap(),
        legacy_base: legacy_base.into(),
        idle_unload: None,
        #[cfg(feature = "native-section-autoconfig")]
        section_autoconfig: native,
        #[cfg(feature = "native-download-targets")]
        download_targets: None,
        #[cfg(feature = "native-badges")]
        badges: None,
        #[cfg(feature = "native-bench-runs")]
        bench_runs: None,
        #[cfg(feature = "native-section-writes")]
        section_writes: None,
        #[cfg(feature = "native-settings-write")]
        settings_write: None,
        #[cfg(feature = "native-benchmark-overview")]
        benchmark_overview: None,
        #[cfg(feature = "native-check-updates")]
        check_updates: None,
        #[cfg(feature = "native-downloads")]
        downloads: None,
        #[cfg(feature = "native-model-delete")]
        model_delete: None,
        #[cfg(feature = "native-draft-heads")]
        draft_heads: None,
        #[cfg(feature = "native-backends")]
        backend_stats: None,
        #[cfg(feature = "native-benchmark-runner")]
        bench_runner: None,
        #[cfg(feature = "native-backend-control")]
        backends: None,
    })
}

struct Answer {
    status: u16,
    content_type: Option<String>,
    body: Vec<u8>,
}

async fn send(state: Arc<StateData>, method: &str, path: &str, token: bool) -> Answer {
    let mut request = Request::builder().method(method).uri(path);
    if token {
        request = request.header("x-model-loader-token", TOKEN);
    }
    let response = noevia_model_manager::router(state)
        .oneshot(request.body(Body::empty()).unwrap())
        .await
        .unwrap();
    Answer {
        status: response.status().as_u16(),
        content_type: response
            .headers()
            .get("content-type")
            .map(|v| v.to_str().unwrap().to_owned()),
        body: response
            .into_body()
            .collect()
            .await
            .unwrap()
            .to_bytes()
            .to_vec(),
    }
}

/// A one-shot stand-in for the Python child: records the request (head and body) and answers
/// `body` with `status`. Returns (base URL, request).
async fn child(status: u16, body: String) -> (String, tokio::task::JoinHandle<(String, String)>) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
    let base = format!("http://{}", listener.local_addr().unwrap());
    let task = tokio::spawn(async move {
        let (mut socket, _) = listener.accept().await.unwrap();
        let mut seen = Vec::new();
        let mut buf = [0u8; 4096];
        let end = loop {
            if let Some(at) = seen.windows(4).position(|w| w == b"\r\n\r\n") {
                break at + 4;
            }
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        };
        let head = String::from_utf8_lossy(&seen[..end]).into_owned();
        let length: usize = head
            .lines()
            .find_map(|l| {
                l.to_ascii_lowercase()
                    .strip_prefix("content-length: ")
                    .map(|v| v.trim().parse().unwrap())
            })
            .unwrap_or(0);
        while seen.len() < end + length {
            let n = socket.read(&mut buf).await.unwrap();
            assert!(n > 0);
            seen.extend_from_slice(&buf[..n]);
        }
        let request_body = String::from_utf8_lossy(&seen[end..end + length]).into_owned();
        let answer = format!(
            "HTTP/1.1 {status} X\r\ncontent-type: application/json\r\ncontent-length: {}\r\nconnection: close\r\n\r\n",
            body.len()
        );
        socket.write_all(answer.as_bytes()).await.unwrap();
        socket.write_all(body.as_bytes()).await.unwrap();
        (head, request_body)
    });
    (base, task)
}

fn hex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}

fn native(models: &Path, cache_cap: i64) -> Arc<SectionAutoconfig> {
    Arc::new(SectionAutoconfig::new(Settings {
        models: models.to_str().unwrap().to_owned(),
        ini: models.join("models.ini").to_str().unwrap().to_owned(),
        cache_ram_cap_mib: cache_cap,
    }))
}

/// One model file `m.gguf` under `root`; returns the models folder.
fn folder(root: &Path) -> std::path::PathBuf {
    let models = root.join("models");
    std::fs::create_dir_all(&models).unwrap();
    std::fs::write(models.join("m.gguf"), hex(HEADER)).unwrap();
    models
}

#[tokio::test]
async fn python_mode_forwards_the_route_unchanged() {
    let path = "/api/v1/sections/m/autoconfig?sessions=2";
    let (base, seen) = child(200, r#"{"legacy":true}"#.into()).await;
    let answer = send(state(None, &base), "GET", path, true).await;
    assert_eq!(answer.body, br#"{"legacy":true}"#);
    let (head, _) = seen.await.unwrap();
    assert!(
        head.starts_with(&format!("GET {path} HTTP/1.1\r\n")),
        "{head}"
    );
}

/// Only GET of the exact shape is native; other methods and shapes answer exactly as they do with
/// the route left to Python (forwarded, or the router's own 405).
#[tokio::test]
async fn other_methods_and_shapes_answer_as_in_python_mode() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    for (method, path) in [
        ("POST", "/api/v1/sections/m/autoconfig"),
        ("PUT", "/api/v1/sections/m/autoconfig"),
        ("GET", "/api/v1/sections/m/autoconfig/"),
        ("GET", "/api/v1/sections/a%2Fb/autoconfig"),
        ("GET", "/api/v1/sections/a/b/autoconfig"),
        ("GET", "/api/v1/sections//autoconfig"),
        ("GET", "/api/v1/sections/m/autoconfigx"),
    ] {
        let mut answers = Vec::new();
        for on in [None, Some(native(&models, 1024))] {
            let (base, _seen) = child(404, r#"{"legacy":true}"#.into()).await;
            let answer = send(state(on, &base), method, path, true).await;
            answers.push((answer.status, answer.body));
        }
        assert_eq!(answers[0], answers[1], "{method} {path}");
        assert_ne!(answers[1].1, REFUSED, "{method} {path}");
    }
}

#[tokio::test]
async fn the_private_runtime_call_is_never_reachable_from_outside() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    for on in [None, Some(native(&models, 1024))] {
        for (method, path) in [
            ("POST", RUNTIME_PATH),
            ("GET", RUNTIME_PATH),
            ("POST", "/api/v1/internal/section-autoconfig-runtim%65"),
        ] {
            let answer = send(state(on.clone(), "http://127.0.0.1:9"), method, path, true).await;
            assert_eq!(answer.status, 404, "{method} {path}");
            assert_eq!(answer.body, br#"{"detail":"Not Found"}"#);
        }
    }
}

#[tokio::test]
async fn the_native_route_keeps_the_token_check() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    let answer = send(
        state(Some(native(&models, 1024)), "http://127.0.0.1:9"),
        "GET",
        "/api/v1/sections/m/autoconfig",
        false,
    )
    .await;
    assert_eq!(answer.status, 401);
    assert_eq!(answer.body, br#"{"error":"unauthorized"}"#);
}

#[cfg(not(target_os = "linux"))]
#[tokio::test]
async fn without_the_contained_opener_the_route_refuses() {
    let dir = tempfile::tempdir().unwrap();
    let models = folder(dir.path());
    let answer = send(
        state(Some(native(&models, 1024)), "http://127.0.0.1:9"),
        "GET",
        "/api/v1/sections/m/autoconfig",
        true,
    )
    .await;
    assert_eq!(answer.status, 503);
    assert_eq!(answer.body, REFUSED);
}

#[cfg(target_os = "linux")]
mod linux {
    use super::*;
    use serde_json::Value;
    use std::io::Write;

    fn fixture() -> Value {
        serde_json::from_str(include_str!("fixtures/section-autoconfig-python.v1.json")).unwrap()
    }

    /// Builds one case like the generator does; returns the models folder.
    fn build(root: &Path, case: &Value) -> std::path::PathBuf {
        let models = root.join("models");
        let Some(files) = case["files"].as_array() else {
            return models;
        };
        std::fs::create_dir(&models).unwrap();
        for spec in files {
            let path = models.join(spec["name"].as_str().unwrap());
            std::fs::create_dir_all(path.parent().unwrap()).unwrap();
            let data = hex(spec["header"].as_str().unwrap_or(""));
            let mut file = std::fs::File::create(&path).unwrap();
            file.write_all(&data).unwrap();
            if let Some(size) = spec["size"].as_u64() {
                if size > data.len() as u64 {
                    file.set_len(size).unwrap();
                }
            }
        }
        if let Some(ini) = case["ini"].as_str() {
            std::fs::write(models.join("models.ini"), ini).unwrap();
        }
        if let Some(roles) = case["roles"].as_str() {
            std::fs::write(models.join("models.roles.json"), roles).unwrap();
        }
        models
    }

    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn every_case_matches_the_actual_python_route_through_the_router() {
        let fixture = fixture();
        let mut checked = 0;
        for case in fixture["cases"].as_array().unwrap() {
            let tmp = tempfile::tempdir().unwrap();
            let models = build(tmp.path(), case);
            let on = native(&models, case["cache_cap"].as_i64().unwrap());
            for result in case["results"].as_array().unwrap() {
                let path = result["path"].as_str().unwrap();
                let runtime = &result["runtime"];
                let (base, seen) = if runtime.is_null() {
                    ("http://127.0.0.1:9".to_owned(), None)
                } else {
                    let status = u16::try_from(runtime["status"].as_u64().unwrap()).unwrap();
                    let (base, seen) =
                        child(status, runtime["body"].as_str().unwrap().to_owned()).await;
                    (base, Some(seen))
                };
                let answer = send(state(Some(on.clone()), &base), "GET", path, true).await;
                let label = format!("case {} {path}", case["id"]);
                assert_eq!(
                    (answer.status, String::from_utf8(answer.body).unwrap()),
                    (
                        u16::try_from(result["status"].as_u64().unwrap()).unwrap(),
                        result["body"].as_str().unwrap().to_owned()
                    ),
                    "{label}"
                );
                if answer.status != 500 {
                    assert_eq!(
                        answer.content_type.as_deref(),
                        result["content_type"].as_str(),
                        "{label}"
                    );
                }
                if let Some(seen) = seen {
                    let (head, body) = seen.await.unwrap();
                    assert!(
                        head.starts_with(&format!("POST {RUNTIME_PATH} HTTP/1.1\r\n")),
                        "{head}"
                    );
                    assert!(
                        head.to_ascii_lowercase()
                            .contains(&format!("x-model-loader-token: {TOKEN}\r\n")),
                        "{head}"
                    );
                    let asked: Value = serde_json::from_str(&body).unwrap();
                    assert_eq!(asked, runtime["request"], "{label}");
                }
                checked += 1;
            }
        }
        assert!(checked >= 100, "{checked}");
    }

    /// The model file is a link out of the models folder: Python would read its target; the
    /// contained reader does not follow it and refuses rather than answer differently.
    #[tokio::test]
    async fn a_link_out_of_the_models_folder_refuses() {
        let dir = tempfile::tempdir().unwrap();
        let models = dir.path().join("models");
        std::fs::create_dir(&models).unwrap();
        let outside = dir.path().join("outside.gguf");
        std::fs::write(&outside, hex(HEADER)).unwrap();
        std::os::unix::fs::symlink(&outside, models.join("m.gguf")).unwrap();
        let answer = send(
            state(Some(native(&models, 1024)), "http://127.0.0.1:9"),
            "GET",
            "/api/v1/sections/m/autoconfig",
            true,
        )
        .await;
        assert_eq!(
            (answer.status, answer.body.as_slice()),
            (503, REFUSED),
            "{}",
            String::from_utf8_lossy(&answer.body)
        );
    }

    #[tokio::test]
    async fn an_unreachable_child_is_the_forwarded_routes_502() {
        let dir = tempfile::tempdir().unwrap();
        let models = folder(dir.path());
        let answer = send(
            state(Some(native(&models, 1024)), "http://127.0.0.1:9"),
            "GET",
            "/api/v1/sections/m/autoconfig",
            true,
        )
        .await;
        assert_eq!((answer.status, answer.body.as_slice()), (502, UNAVAILABLE));
    }
}
